class Solution {
  public int[][] reverseSubmatrix(int[][] grid, int x, int y, int k) {
    for (int top = x, bottom = x + k - 1; top < bottom; top++, bottom--) {
      for (int c = y; c < y + k; c++) {
        int t = grid[top][c];
        grid[top][c] = grid[bottom][c];
        grid[bottom][c] = t;
      }
    }
    return grid;
  }
}
